import React from "react";
import { Link, useLocation } from "react-router-dom";
import { FaUsers, FaChalkboardTeacher, FaUser, FaTachometerAlt } from "react-icons/fa";

const Sidebar = () => {
  const location = useLocation();

  const linkClass = (path) =>
    `flex items-center p-3 rounded-lg transition-colors ${
      location.pathname === path ? "bg-blue-600 text-white" : "hover:bg-gray-200"
    }`;

  return (
    <div className="w-64 h-screen bg-gray-100 shadow-lg p-5">
      <h2 className="text-2xl font-bold mb-6">Admin Panel</h2>

      <nav className="flex flex-col gap-3">
        <Link to="/admin-dashboard" className={linkClass("/admin-dashboard")}>
          <FaTachometerAlt className="mr-3" /> Dashboard
        </Link>
        <Link to="/admin-dashboard/students" className={linkClass("/admin-dashboard/students")}>
          <FaUsers className="mr-3" /> Students
        </Link>
        <Link to="/admin-dashboard/teachers" className={linkClass("/admin-dashboard/teachers")}>
          <FaChalkboardTeacher className="mr-3" /> Teachers
        </Link>
        <Link to="/admin-dashboard/profile" className={linkClass("/admin-dashboard/profile")}>
          <FaUser className="mr-3" /> Profile
        </Link>
      </nav>
    </div>
  );
};

export default Sidebar;
